class Ball(GameItem, ThreadBase):          # real multiple inheritance
    def __init__(self, x, y):
        super().__init__()                 # cooperative: MRO drives both bases
        self.x, self.y, self.suspended = x, y, False
    def click(self):
        self.suspended = not self.suspended
    def run(self):
        while not self.suspended:          # no twin object, no back-reference
            self.draw(); self.move()

print(Ball.__mro__)   # Ball, GameItem, ThreadBase, object
